 {step===0?<><div className="panel-head"><div><h2>Identifique o serviço</h2><p>Você pode assumir em qualquer um dos três municípios.</p></div><Badge tone="blue">Referência: 10h</Badge></div><div className="form-body"><label className="field">Município do serviço<NativeSelect value={checkCity} onChange={e=>void changeCheckCity(e.target.value)}>{CITIES.map(c=><option key={c}>{c}</option>)}</NativeSelect></label><div className="responsible"><ShieldCheck size={22}/><span><small>RESPONSÁVEL PELO REGISTRO</small><strong>{myOfficer?myOfficer.rank+' '+myOfficer.name:data.user.name}</strong><small>{myOfficer?'Matrícula '+myOfficer.registration:'Vínculo policial pendente'}</small></span></div><label className="field">Guarnição <span className="muted">Selecione os policiais que assumem com você</span></label><div className="crew-search"><Search size={17}/><input placeholder="Buscar nome ou matrícula" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="crew-grid">{data.officers.filter(o=>o.active&&o.validated&&`${o.name} ${o.callsign} ${o.registration}`.toLowerCase().includes(search.toLowerCase())).map(o=><label className={crew.includes(o.id)?'crew selected':'crew'} key={o.id}><Checkbox checked={crew.includes(o.id)} disabled={o.id===data.user.officer_id} onChange={e=>setCrew(e.target.checked?[...crew,o.id]:crew.filter(id=>id!==o.id))}/><span><strong>{o.rank} {o.callsign}</strong><small>{o.city} · {o.registration}</small></span></label>)}</div><label className="field">Observações do serviço (opcional)<textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Informações relevantes para a passagem de serviço…"/></label></div></>:step===1?<><div className="panel-head"><div><h2>Materiais de {checkCity}</h2><p>Confira a identificação e as quantidades encontradas.</p></div><Badge tone="blue">{completed}/{entries.length} conferidos</Badge></div><div className="category-tabs"><button className={checkCategory==='todos'?'selected':''} onClick={()=>setCheckCategory('todos')}>Todos</button>{data.categories.filter(c=>entries.some(e=>e.category===c.id)).map(c=><button className={checkCategory===c.id?'selected':''} onClick={()=>setCheckCategory(c.id)} key={c.id}>{c.name}</button>)}</div><div className="check-items">{checkItems.filter(i=>checkCategory==='todos'||i.category===checkCategory).map(i=>{const e=entries.find(e=>e.id===i.id);if(!e)return null;const issue=needsJustification(e,i.quantity)&&e.quantity!==null;const move=activeMoves.find(m=>m.item_id===i.id);return <article className={'check-item '+(issue?'with-issue':'')} key={i.id}><div className="check-item-head"><div><strong>{i.name}</strong><small>{i.serial||'Controle quantitativo'}{i.caliber?' · Calibre '+i.caliber:''}</small></div><Badge>Previsto: {i.quantity}</Badge></div>{move&&<div className="small-notice">Cautela {move.status==='recebida'?'recebida':'aguardando recebimento'} · {crewLabels([move.officer_id])} · {move.destination}. Registre a quantidade efetivamente encontrada.</div>}<div className="check-inputs"><label className="field">Condição<NativeSelect value={e.condition} onChange={ev=>updateEntry(i.id,{condition:ev.target.value,...(ev.target.value==='Não encontrado'?{quantity:0}:i.serial?{quantity:1}:{})})}><option value="">Selecione…</option>{CONDITIONS.map(c=><option key={c}>{c}</option>)}</NativeSelect></label><label className="field">Quantidade encontrada<input inputMode="numeric" type="number" min="0" max={i.serial?1:undefined} value={e.quantity??''} onChange={ev=>updateEntry(i.id,{quantity:ev.target.value===''?null:Number(ev.target.value)})}/></label>{e.quantity!==null&&<div className={'difference '+(e.quantity!==i.quantity?'negative':'positive')}><small>DIFERENÇA</small><strong>{e.quantity-i.quantity>0?'+':''}{e.quantity-i.quantity}</strong></div>}<button className="text-link quick-check" onClick={()=>updateEntry(i.id,{quantity:i.quantity,condition:'Bom'})}><Check size={15}/> Conforme previsto</button></div><label className="checkbox-line"><Checkbox checked={e.identification} onChange={ev=>updateEntry(i.id,{identification:ev.target.checked})}/> Identificação patrimonial divergente</label><label className="field">{issue?'Justificativa obrigatória':'Observações (opcional)'}<textarea className={issue&&!e.notes.trim()?'required':''} value={e.notes} onChange={ev=>updateEntry(i.id,{notes:ev.target.value})} placeholder={e.condition==='Não encontrado'?'Informe as circunstâncias da ausência ou a cautela conhecida…':'Avarias, divergências ou informações relevantes…'}/></label></article>})}</div></>:<><div className="panel-head"><div><h2>Revise a conferência</h2><p>Após a finalização, o registro será preservado no histórico.</p></div><Badge tone="blue">{checkCity}</Badge></div><div className="form-body"><div className="review-summary"><span><small>RESPONSÁVEL</small><strong>{data.user.name}</strong></span><span><small>GUARNIÇÃO</small><strong>{crewLabels(crew)}</strong></span></div><div className="table-wrap"><Table><TableHeader><TableRow><TableHead>Material</TableHead><TableHead>Previsto</TableHead><TableHead>Conferido</TableHead><TableHead>Condição</TableHead></TableRow></TableHeader><TableBody>{entries.map(e=><TableRow key={e.id}><TableCell><strong>{e.name}</strong><small>{e.serial}</small>{e.notes&&<small>{e.notes}</small>}</TableCell><TableCell>{e.expected}</TableCell><TableCell>{e.quantity??'Pendente'}</TableCell><TableCell><Badge tone={needsJustification(e,e.expected||0)?'amber':'green'}>{e.condition||'Pendente'}</Badge></TableCell></TableRow>)}</TableBody></Table></div>{notes&&<p className="review-notes"><strong>Observações do serviço:</strong> {notes}</p>}<label className="review-confirm"><Checkbox checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/><span>Conferi os materiais, revisei os dados e assumo a responsabilidade por este registro.</span></label></div></>}
