 {view==='movements'&&<><div className="toolbar"><div className="search"><Search size={18}/><input placeholder="Buscar material ou responsável…" value={search} onChange={e=>setSearch(e.target.value)}/></div><NativeSelect aria-label="Município da movimentação" value={city} onChange={e=>setCity(e.target.value)}><option>Todos os municípios</option>{CITIES.map(c=><option key={c}>{c}</option>)}</NativeSelect></div><div className="panel"><div className="panel-head"><h2>Registro de cautelas</h2><Badge tone="blue">{activeMoves.length} em andamento</Badge></div>{data.movements.length?<div className="table-wrap"><Table><TableHeader><TableRow><TableHead>Material / responsável</TableHead><TableHead>Origem / destino</TableHead><TableHead>Retirada / prazo</TableHead><TableHead>Situação</TableHead><TableHead>Ação</TableHead></TableRow></TableHeader><TableBody>{data.movements.filter(m=>(city==='Todos os municípios'||m.origin===city||m.destination===city)&&`${m.item_name} ${crewLabels([m.officer_id])}`.toLowerCase().includes(search.toLowerCase())).map(m=><TableRow key={m.id}><TableCell><strong>{m.item_name}</strong><small>{crewLabels([m.officer_id])} · {m.quantity} unidade(s)</small><small>{m.notes}</small></TableCell><TableCell>{m.origin}<small>Destino: {m.destination}</small></TableCell><TableCell>{dateTime(m.withdrawn_at)}<small>{m.due_at?'Prazo: '+dateTime(m.due_at):'Sem prazo previsto'}</small></TableCell><TableCell><Badge tone={m.status==='devolvida'?'green':m.due_at&&new Date(m.due_at)<new Date()?'red':'amber'}>{m.status==='devolvida'?'Devolvida':m.status==='recebida'?'Sob cautela':'Confirmar recebimento'}</Badge>{m.received_at&&<small>Recebido: {dateTime(m.received_at)}</small>}{m.returned_at&&<small>Devolvido: {dateTime(m.returned_at)}</small>}</TableCell><TableCell>{isAdmin&&m.status!=='devolvida'&&<Button secondary disabled={busy} onClick={()=>openForm('confirm-movement',m)}>{m.status==='aguardando'?'Confirmar recebimento':'Registrar devolução'}</Button>}</TableCell></TableRow>)}</TableBody></Table></div>:<Empty icon={ArrowLeftRight} title="Nenhuma cautela registrada" description="Registre a retirada de um material para acompanhar o responsável, a localização e a devolução." action={isAdmin?<Button onClick={()=>openForm('movement')}><Plus size={17}/> Registrar cautela</Button>:undefined}/>}<div className="panel-foot">A vinculação patrimonial é preservada. A localização é atualizada na confirmação de recebimento.</div></div></>}
